package teksturepako.pakkuDesktop.pro.ui.component.diff

import androidx.compose.foundation.background
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.Row
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.fillMaxWidth
import androidx.compose.foundation.layout.padding
import androidx.compose.foundation.layout.width
import androidx.compose.foundation.rememberScrollState
import androidx.compose.foundation.text.selection.SelectionContainer
import androidx.compose.foundation.verticalScroll
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalDensity
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.text.rememberTextMeasurer
import androidx.compose.ui.text.style.TextAlign
import androidx.compose.ui.text.style.TextOverflow
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.dp
import org.jetbrains.jewel.foundation.theme.JewelTheme
import org.jetbrains.jewel.ui.component.Text
import teksturepako.pakkuDesktop.pro.ui.viewmodel.state.DiffContent
import teksturepako.pakkuDesktop.pro.ui.viewmodel.state.DiffType

/**
 * Read-only diff view.
 *
 * Layout is driven purely by Compose — no canvas drawing, no magic numbers.
 * Column widths are derived from actual font metrics measured at runtime, so
 * they stay correct when the font family, size, or system DPI changes.
 *
 * Structure of each content line:
 *   [ old line# ][ new line# ][ prefix ][ source text … ]
 * Hunk-header lines span the full width.
 */
@Composable
internal fun DiffTextArea(
    diff: DiffContent,
    modifier: Modifier = Modifier,
) {
    val rendered = remember(diff) { buildRenderedDiff(diff) }

    val editorStyle    = JewelTheme.editorTextStyle.copy(fontFamily = FontFamily.Monospace)
    val gutterFg       = diffGutterLabelColor()
    val gutterStyle    = editorStyle.copy(color = gutterFg)

    val addedStyle     = diffLineStyle(DiffType.ADDED)
    val deletedStyle   = diffLineStyle(DiffType.DELETED)
    val unchangedStyle = diffLineStyle(DiffType.UNCHANGED)
    val hunkBg         = diffHunkHeaderBackground()
    val headerFg       = diffHunkHeaderForeground()

    val textMeasurer = rememberTextMeasurer()
    val density      = LocalDensity.current

    // ── Column widths from font metrics ──────────────────────────────────────
    // "99999" is the widest plausible 5-digit line number; measuring it gives
    // the exact pixel width for the current font without any guessing.
    val lineNumTextWidth: Dp = remember(gutterStyle) {
        with(density) {
            textMeasurer.measure("99999", style = gutterStyle, maxLines = 1)
                .size.width.toDp()
        }
    }
    // All diff-prefix characters (+, -, space) are one monospace glyph wide.
    val prefixTextWidth: Dp = remember(editorStyle) {
        with(density) {
            textMeasurer.measure("+", style = editorStyle, maxLines = 1)
                .size.width.toDp()
        }
    }

    // Horizontal padding that gives the columns breathing room.
    // This is a deliberate design value, not a compensation for misalignment.
    val colPadding: Dp = 6.dp

    val lineNumColWidth: Dp = lineNumTextWidth + colPadding * 2
    val prefixColWidth: Dp  = prefixTextWidth  + colPadding * 2

    // ── Render ───────────────────────────────────────────────────────────────
    SelectionContainer(modifier = modifier.fillMaxSize()) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .verticalScroll(rememberScrollState()),
        ) {
            for (line in rendered.lines)
            {
                val background = when (line.kind) {
                    DiffRenderedLineKind.ADDED       -> addedStyle.lineBackground
                    DiffRenderedLineKind.DELETED     -> deletedStyle.lineBackground
                    DiffRenderedLineKind.UNCHANGED   -> unchangedStyle.lineBackground
                    DiffRenderedLineKind.HUNK_HEADER -> hunkBg
                }

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(background),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    if (line.kind == DiffRenderedLineKind.HUNK_HEADER)
                    {
                        // Hunk header spans the whole row.
                        Text(
                            text = line.hunkHeader,
                            style = editorStyle.copy(color = headerFg),
                            modifier = Modifier
                                .weight(1f)
                                .padding(horizontal = colPadding),
                            maxLines = 1,
                            softWrap = false,
                            overflow = TextOverflow.Clip,
                        )
                    }
                    else
                    {
                        // Old line number — right-aligned in its measured column.
                        Text(
                            text = line.oldNum?.toString() ?: "",
                            style = gutterStyle,
                            modifier = Modifier
                                .width(lineNumColWidth)
                                .padding(horizontal = colPadding),
                            maxLines = 1,
                            textAlign = TextAlign.End,
                        )
                        // New line number — same layout as old.
                        Text(
                            text = line.newNum?.toString() ?: "",
                            style = gutterStyle,
                            modifier = Modifier
                                .width(lineNumColWidth)
                                .padding(horizontal = colPadding),
                            maxLines = 1,
                            textAlign = TextAlign.End,
                        )
                        // Diff prefix (+/-/space).
                        Text(
                            text = line.prefix,
                            style = editorStyle.copy(
                                color = when (line.kind) {
                                    DiffRenderedLineKind.ADDED   -> addedStyle.prefixColor
                                    DiffRenderedLineKind.DELETED -> deletedStyle.prefixColor
                                    else                         -> gutterFg
                                },
                            ),
                            modifier = Modifier
                                .width(prefixColWidth)
                                .padding(horizontal = colPadding),
                            maxLines = 1,
                            textAlign = TextAlign.Center,
                        )
                        // Source line content — takes the remaining width.
                        Text(
                            text = line.sourceText,
                            style = editorStyle,
                            modifier = Modifier
                                .weight(1f)
                                .padding(end = colPadding),
                            softWrap = false,
                            overflow = TextOverflow.Clip,
                        )
                    }
                }
            }
        }
    }
}

// ── Data model ───────────────────────────────────────────────────────────────

private enum class DiffRenderedLineKind
{
    HUNK_HEADER,
    ADDED,
    DELETED,
    UNCHANGED,
}

private data class RenderedDiffLine(
    val kind: DiffRenderedLineKind,
    val sourceText: String,
    /** Non-empty only for [DiffRenderedLineKind.HUNK_HEADER] lines. */
    val hunkHeader: String = "",
    /** Non-null only for non-header lines. */
    val oldNum: Int? = null,
    val newNum: Int? = null,
    val prefix: String = " ",
)

private data class RenderedDiff(
    val lines: List<RenderedDiffLine>,
)

// ── Builder ──────────────────────────────────────────────────────────────────

private fun buildRenderedDiff(diff: DiffContent): RenderedDiff
{
    val lines = ArrayList<RenderedDiffLine>(diff.hunks.sumOf { it.lines.size + 1 })

    for (hunk in diff.hunks)
    {
        lines += RenderedDiffLine(
            kind       = DiffRenderedLineKind.HUNK_HEADER,
            sourceText = "",
            hunkHeader = hunk.header,
        )
        for (line in hunk.lines)
        {
            lines += RenderedDiffLine(
                kind       = line.type.toKind(),
                sourceText = line.content,
                oldNum     = line.number.old,
                newNum     = line.number.new,
                prefix     = line.type.toPrefix(),
            )
        }
    }

    return RenderedDiff(lines = lines)
}

private fun DiffType.toKind(): DiffRenderedLineKind = when (this) {
    DiffType.ADDED     -> DiffRenderedLineKind.ADDED
    DiffType.DELETED   -> DiffRenderedLineKind.DELETED
    DiffType.UNCHANGED -> DiffRenderedLineKind.UNCHANGED
}

private fun DiffType.toPrefix(): String = when (this) {
    DiffType.ADDED     -> "+"
    DiffType.DELETED   -> "-"
    DiffType.UNCHANGED -> " "
}

